"<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    html, body {
      width: 100vw;
      height: 100vh;
      overflow: hidden;
      display: flex;
      justify-content: center;
      align-items: center;
      background: #f0f0f0;
    }

    .keyboard {
      width: 95%;
      height: 95%;
      display: grid;
      grid-template-rows: repeat(6, 1fr);
      gap: 1px;
      padding: 2px;
      background: #ddd;
    }

    .row {
      display: flex;
      gap: 1px;
    }

    .key {
      display: flex;
      justify-content: center;
      align-items: center;
      text-align: center;
      font-family: sans-serif;
      font-size: 0.7em;
      line-height: 1;
      padding: 0;
      border: 1px solid #999;
      background: white;
      color: black;
      cursor: pointer;
      word-break: break-all;
      min-height: 0;
    }

    /* Пропорции клавиш */
    .row:nth-child(1) .key { flex: 1; }
    .row:nth-child(2) .key { flex: 1; }
    .row:nth-child(3) .key { flex: 1; }
    .row:nth-child(4) .key { flex: 1; }
    .row:nth-child(5) .key { flex: 1; }
    .row:nth-child(6) .key { flex: 1; }

    /* F-строка — маленькие клавиши */
    .row:nth-child(1) .key { flex: 0.7; }
    .row:nth-child(1) .key:nth-child(n+14) { flex: 0.9; }

    /* Строка 2 */
    .row:nth-child(2) .key:nth-child(14) { flex: 2; }
    .row:nth-child(2) .key:nth-child(15) { flex: 1.2; }

    /* Строка 3 */
    .row:nth-child(3) .key:nth-child(1) { flex: 1.5; }
    .row:nth-child(3) .key:nth-child(15) { flex: 1.5; }

    /* Строка 4 */
    .row:nth-child(4) .key:nth-child(1) { flex: 1.5; }
    .row:nth-child(4) .key:nth-child(14) { flex: 2; }
    .row:nth-child(4) .key:nth-child(15) { flex: 1.5; }

    /* Строка 5 */
    .row:nth-child(5) .key:nth-child(1) { flex: 2; }
    .row:nth-child(5) .key:nth-child(12) { flex: 2; }
    .row:nth-child(5) .key:nth-child(13) { flex: 1.5; }

    /* Строка 6 */
    .row:nth-child(6) .key:nth-child(1) { flex: 1.2; }
    .row:nth-child(6) .key:nth-child(2) { flex: 1.2; }
    .row:nth-child(6) .key:nth-child(3) { flex: 1.2; }
    .row:nth-child(6) .key:nth-child(4) { flex: 4; }
    .row:nth-child(6) .key:nth-child(5) { flex: 1.2; }
    .row:nth-child(6) .key:nth-child(6) { flex: 1.2; }
    .row:nth-child(6) .key:nth-child(7) { flex: 1.5; } /* ← */
    .row:nth-child(6) .key:nth-child(8) { flex: 1.5; } /* ↑ */
    .row:nth-child(6) .key:nth-child(9) { flex: 1.5; } /* ↓ */
    .row:nth-child(6) .key:nth-child(10) { flex: 1.5; } /* → */
  </style>
</head>
<body>
  <div class="keyboard">
    <div class="row">
      <button class="key" onclick="sendKey('ESC')">Esc</button>
      <button class="key" onclick="sendKey('VK_F1')">F1</button>
      <button class="key" onclick="sendKey('SC_F2')">F2</button>
      <button class="key" onclick="sendKey('FKEY1')">F3</button>
      <button class="key" onclick="sendKey('F_ONE')">F4</button>
      <button class="key" onclick="sendKey('FUNC_10')">F5</button>
