            <h3>KOLZYY MOD MENU TEMPLATE</h3>
            <p>by @KolzyyF</p>
        </div>

        <div class="settings-section">
            <div class="section-title">⚙️ НАСТРОЙКИ ЧИТА</div>

            <div class="checkbox-item" onclick="document.getElementById('chk_aimbot').click()">
                <input type="checkbox" id="chk_aimbot">
                <span class="custom-checkbox"></span>
                <label>🔫 AimBot</label>
            </div>

            <div class="checkbox-item" onclick="document.getElementById('chk_esp').click()">
                <input type="checkbox" id="chk_esp">
                <span class="custom-checkbox"></span>
                <label>👁️ ESP</label>
            </div>

            <div class="checkbox-item" onclick="document.getElementById('chk_speed').click()">
                <input type="checkbox" id="chk_speed">
                <span class="custom-checkbox"></span>
                <label>⚡ SpeedHack</label>
            </div>

            <div class="checkbox-item" onclick="document.getElementById('chk_skin').click()">
                <input type="checkbox" id="chk_skin">
                <span class="custom-checkbox"></span>
                <label>🎨 Skin Changer</label>
            </div>

            <div class="checkbox-item" onclick="document.getElementById('chk_ammo').click()">
                <input type="checkbox" id="chk_ammo">
                <span class="custom-checkbox"></span>
                <label>📦 Infinite Ammo</label>
            </div>
        </div>

        <div class="buttons-section">
            <button class="glow-on-hover" onclick="applySettings()">✅ ПРИМЕНИТЬ</button>
            <button class="btnpro" onclick="sendCommand('telegram')">📱 TELEGRAM</button>
            <button class="btnpro exit-btn" onclick="sendCommand('exit')">❌ ВЫХОД</button>
        </div>
    </div>

    <script>
        // Функция отправки (как в вашем примере)
        function sendCommand(text) {
            if (window.Android && Android.postMessage) {
                Android.postMessage(text);
            }
        }

        // ПРИМЕНИТЬ - собираем ВСЕ включённые галочки
        function applySettings() {
            const aimbot = document.getElementById('chk_aimbot').checked;
            const esp = document.getElementById('chk_esp').checked;
            const speedhack = document.getElementById('chk_speed').checked;
            const skinchanger = document.getElementById('chk_skin').checked;
            const infiniteAmmo = document.getElementById('chk_ammo').checked;

            // Собираем ВСЕ включённые параметры в массив
            const enabled = [];

            if (aimbot) enabled.push('aimbot');
            if (esp) enabled.push('esp');
            if (speedhack) enabled.push('speed');
            if (skinchanger) enabled.push('skin');
            if (infiniteAmmo) enabled.push('ammo');

            // Если ничего не выбрано - не отправляем
            if (enabled.length === 0) {
                return;
            }

            // Формируем команду: apply_aimbot+esp+speed+skin+ammo
            const command = 'apply_' + enabled.join('+');

            // Отправляем
            sendCommand(command);
        }
    </script>
