<body>

    <div class="title-bar">SCENE_HIERARCHY</div>

    <div id="hierarchy"></div>

    <div class="unselect-btn" onclick="unselectMode()">[ UNSELECT ]</div>

    <script>
        const list = document.getElementById('hierarchy');

        function processObject(dataString) {
            const parts = dataString.split(',');
            const name = parts[0] || "OBJ";
            const id = parts[1] || "0";

            if (document.getElementById('obj-' + id)) return;

            const div = document.createElement('div');
            div.id = 'obj-' + id;
            div.className = 'item';
            div.innerHTML = `<span class="name">${name.toUpperCase()}</span><span class="id-label">#${id}</span>`;

            div.onclick = function() {
                document.querySelectorAll('.item').forEach(el => el.classList.remove('active'));
                div.classList.add('active');

                const message = name + "," + id;
                if (window.Android && window.Android.postMessage) {
                    window.Android.postMessage(message);
                }
            };

            list.appendChild(div);
            list.scrollTop = list.scrollHeight;
        }

        function unselectMode() {
            document.querySelectorAll('.item').forEach(el => el.classList.remove('active'));
            if (window.Android && window.Android.postMessage) {
                window.Android.postMessage("NONE,0");
            }
        }

        function removeObject(dataString) {
            const parts = String(dataString).split(',');
            let id = parts.length > 1 ? parts[1] : parts[0];
            id = id.trim().split('.')[0];

            const targetId = 'obj-' + id;
            const el = document.getElementById(targetId);
            if (el) el.remove();
        }

        function clearList() { 
            list.innerHTML = ''; 
        }
    </script>
</body>
</html>"

