</head>
<body>

<div id="gameContainer">
    <div id="scoreDisplay">0</div>
    <canvas id="gameCanvas" width="400" height="600"></canvas>

    <div id="mobileControls">
        <div id="leftBtn" class="touch-btn">◀</div>
        <div id="rightBtn" class="touch-btn">▶</div>
    </div>

    <div id="mainMenu" class="ui-screen">
        <h1>Jumper</h1>
        <p>Управление на ПК: Стрелки или A/D<br>На телефоне: Нажимайте по краям экрана</p>
        <button id="startBtn">Играть</button>
    </div>

    <div id="gameOverScreen" class="ui-screen hidden">
        <h1>Игра окончена</h1>
        <p>Ваш счет: <span id="finalScore">0</span></p>
        <button id="restartBtn">Повторить</button>
    </div>
</div>

<script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');

    const mainMenu = document.getElementById('mainMenu');
    const gameOverScreen = document.getElementById('gameOverScreen');
    const scoreDisplay = document.getElementById('scoreDisplay');
    const mobileControls = document.getElementById('mobileControls');
    const finalScore = document.getElementById('finalScore');
    const startBtn = document.getElementById('startBtn');
    const restartBtn = document.getElementById('restartBtn');
    const leftBtn = document.getElementById('leftBtn');
    const rightBtn = document.getElementById('rightBtn');

    let gameState = 'menu';
    let animationId;

    let score = 0;
    let totalHeightClimbed = 0; 

    const player = {
        x: 200,
        y: 300,
        width: 30,
        height: 30,
        dx: 0,
        dy: 0,
        jumpPower: -10,
        gravity: 0.4,
        speed: 6
    };

    let platforms = [];
    const platformWidth = 60;
    const platformHeight = 15;
    const platformCount = 7;
    const maxHorizontalGap = 130; // Максимальное расстояние по горизонтали между платформами

    let keys = { left: false, right: false };

    document.addEventListener('keydown', (e) => {
        if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = true;
        if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = true;
    });

    document.addEventListener('keyup', (e) => {
        if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = false;
        if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = false;
    });

    leftBtn.addEventListener('touchstart', (e) => { e.preventDefault(); keys.left = true; });
    leftBtn.addEventListener('touchend', (e) => { e.preventDefault(); keys.left = false; });
    rightBtn.addEventListener('touchstart', (e) => { e.preventDefault(); keys.right = true; });
    rightBtn.addEventListener('touchend', (e) => { e.preventDefault(); keys.right = false; });

    leftBtn.addEventListener('mousedown', () => keys.left = true);
    leftBtn.addEventListener('mouseup', () => keys.left = false);
    leftBtn.addEventListener('mouseleave', () => keys.left = false);
    rightBtn.addEventListener('mousedown', () => keys.right = true);
    rightBtn.addEventListener('mouseup', () => keys.right = false);
    rightBtn.addEventListener('mouseleave', () => keys.right = false);

    // Функция генерации безопасной X координаты относительно предыдущей платформы
    function getNextPlatformX(prevX) {
        // Выбираем случайное смещение от -maxHorizontalGap до +maxHorizontalGap
        let offset = (Math.random() * 2 - 1) * maxHorizontalGap;
        let newX = prevX + offset;

        // Удерживаем платформу в пределах видимости экрана
        if (newX < 0) newX = 0;
        if (newX > canvas.width - platformWidth) newX = canvas.width - platformWidth;

        return newX;
    }

    function initPlatforms() {
        platforms = [];
        let currentY = player.y + 50;
        let lastX = player.x - platformWidth / 2;

        // Первая платформа строго под игроком
        platforms.push({ x: lastX, y: currentY });

        for (let i = 1; i < platformCount; i++) {
            let gapY = 75 + Math.random() * 35;
            currentY -= gapY;

            // Генерируем X на основе предыдущей платформы
            let nextX = getNextPlatformX(lastX);
            platforms.push({ x: nextX, y: currentY });
            lastX = nextX;
        }
    }

    function resetGame() {
        player.x = canvas.width / 2;
        player.y = canvas.height / 2;
        player.dx = 0;
        player.dy = 0;
        score = 0;
        totalHeightClimbed = 0;
        scoreDisplay.innerText = score;
        initPlatforms();
    }

    function drawPlayer() {
        ctx.fillStyle = '#4CAF50';
        ctx.fillRect(player.x - player.width / 2, player.y - player.height / 2, player.width, player.height);

        ctx.fillStyle = '#fff';
        let eyeOffset = keys.left ? -3 : (keys.right ? 3 : 0);

        ctx.fillRect(player.x - 8 + eyeOffset, player.y - 10, 6, 6);
        ctx.fillRect(player.x + 2 + eyeOffset, player.y - 10, 6, 6);
        ctx.fillStyle = '#000';
        ctx.fillRect(player.x - 6 + eyeOffset, player.y - 8, 2, 2);
        ctx.fillRect(player.x + 4 + eyeOffset, player.y - 8, 2, 2);
    }

    function drawPlatforms() {
        ctx.fillStyle = '#8BC34A';
        platforms.forEach(p => {
            ctx.fillRect(p.x, p.y, platformWidth, platformHeight);
            ctx.fillStyle = '#689F38';
            ctx.fillRect(p.x, p.y + platformHeight - 3, platformWidth, 3);
            ctx.fillStyle = '#8BC34A';
        });
    }

    function update() {
        if (gameState !== 'playing') return;

        if (keys.left) player.x -= player.speed;
        if (keys.right) player.x += player.speed;

        if (player.x < 0) player.x = canvas.width;
        if (player.x > canvas.width) player.x = 0;

        player.dy += player.gravity;
        player.y += player.dy;

        if (player.dy > 0) {
            platforms.forEach(p => {
                if (
                    player.y + player.height / 2 >= p.y &&
                    player.y + player.height / 2 <= p.y + platformHeight &&
                    player.x + player.width / 2 > p.x &&
                    player.x - player.width / 2 < p.x + platformWidth
                ) {
                    player.dy = player.jumpPower;
                }
            });
        }

        if (player.y < canvas.height / 2) {
            let offset = canvas.height / 2 - player.y;
            player.y = canvas.height / 2;

            totalHeightClimbed += offset;
            score = Math.floor(totalHeightClimbed / 5);
            scoreDisplay.innerText = score;

            platforms.forEach(p => { p.y += offset; });

            // Ищем самую высокую платформу на данный момент по координате Y,
            // а также сохраняем её координату X, чтобы отталкиваться от неё
            let highestY = canvas.height;
            let highestX = canvas.width / 2;

            platforms.forEach(p => {
                if (p.y < highestY && p.y <= canvas.height) {
                    highestY = p.y;
                    highestX = p.x;
                }
            });

            // ИСПРАВЛЕНИЕ: Переносим улетевшие платформы с умным расчётом по X и Y
            for (let i = 0; i < platforms.length; i++) {
                if (platforms[i].y > canvas.height) {
                    let gapY = 75 + Math.random() * 35;

                    platforms[i].y = highestY - gapY;
                    // Генерируем X поблизости от текущей самой верхней платформы
                    platforms[i].x = getNextPlatformX(highestX);

                    // Обновляем верхние ориентиры для следующей итерации
                    highestY = platforms[i].y; 
                    highestX = platforms[i].x;
                }
            }
        }

        if (player.y > canvas.height) {
            gameState = 'gameover';
            finalScore.innerText = score;
            scoreDisplay.style.display = 'none';
            mobileControls.style.display = 'none';
            gameOverScreen.classList.remove('hidden');
        }
    }

    function loop() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        if (gameState === 'playing') {
            update();
            drawPlatforms();
            drawPlayer();
        }
        animationId = requestAnimationFrame(loop);
    }

    function startGame() {
        mainMenu.classList.add('hidden');
        gameOverScreen.classList.add('hidden');
        scoreDisplay.style.display = 'block';
        mobileControls.style.display = 'block';
        resetGame();
        gameState = 'playing';
    }

    startBtn.addEventListener('click', startGame);
    restartBtn.addEventListener('click', startGame);

    resetGame();
    loop();
</script>

</body>
</html>"

