        platforms.push({ x: lastX, y: currentY });

        for (let i = 1; i < platformCount; i++) {
            let gapY = 75 + Math.random() * 35;
            currentY -= gapY;

            // Генерируем X на основе предыдущей платформы
            let nextX = getNextPlatformX(lastX);
            platforms.push({ x: nextX, y: currentY });
            lastX = nextX;
        }
    }

    function resetGame() {
        player.x = canvas.width / 2;
        player.y = canvas.height / 2;
        player.dx = 0;
        player.dy = 0;
        score = 0;
        totalHeightClimbed = 0;
        scoreDisplay.innerText = score;
        initPlatforms();
    }

    function drawPlayer() {
        ctx.fillStyle = '#4CAF50';
        ctx.fillRect(player.x - player.width / 2, player.y - player.height / 2, player.width, player.height);

        ctx.fillStyle = '#fff';
        let eyeOffset = keys.left ? -3 : (keys.right ? 3 : 0);

        ctx.fillRect(player.x - 8 + eyeOffset, player.y - 10, 6, 6);
        ctx.fillRect(player.x + 2 + eyeOffset, player.y - 10, 6, 6);
        ctx.fillStyle = '#000';
        ctx.fillRect(player.x - 6 + eyeOffset, player.y - 8, 2, 2);
        ctx.fillRect(player.x + 4 + eyeOffset, player.y - 8, 2, 2);
    }

    function drawPlatforms() {
        ctx.fillStyle = '#8BC34A';
        platforms.forEach(p => {
            ctx.fillRect(p.x, p.y, platformWidth, platformHeight);
            ctx.fillStyle = '#689F38';
            ctx.fillRect(p.x, p.y + platformHeight - 3, platformWidth, 3);
            ctx.fillStyle = '#8BC34A';
        });
    }

    function update() {
        if (gameState !== 'playing') return;

        if (keys.left) player.x -= player.speed;
        if (keys.right) player.x += player.speed;

        if (player.x < 0) player.x = canvas.width;
        if (player.x > canvas.width) player.x = 0;

        player.dy += player.gravity;
        player.y += player.dy;

        if (player.dy > 0) {
            platforms.forEach(p => {
                if (
                    player.y + player.height / 2 >= p.y &&
                    player.y + player.height / 2 <= p.y + platformHeight &&
                    player.x + player.width / 2 > p.x &&
                    player.x - player.width / 2 < p.x + platformWidth
                ) {
                    player.dy = player.jumpPower;
                }
            });
        }

        if (player.y < canvas.height / 2) {
            let offset = canvas.height / 2 - player.y;
            player.y = canvas.height / 2;

            totalHeightClimbed += offset;
            score = Math.floor(totalHeightClimbed / 5);
            scoreDisplay.innerText = score;

            platforms.forEach(p => { p.y += offset; });

            // Ищем самую высокую платформу на данный момент по координате Y,
            // а также сохраняем её координату X, чтобы отталкиваться от неё
            let highestY = canvas.height;
            let highestX = canvas.width / 2;

            platforms.forEach(p => {
                if (p.y < highestY && p.y <= canvas.height) {
                    highestY = p.y;
                    highestX = p.x;
                }
            });

            // ИСПРАВЛЕНИЕ: Переносим улетевшие платформы с умным расчётом по X и Y
            for (let i = 0; i < platforms.length; i++) {
                if (platforms[i].y > canvas.height) {
                    let gapY = 75 + Math.random() * 35;

                    platforms[i].y = highestY - gapY;
                    // Генерируем X поблизости от текущей самой верхней платформы
                    platforms[i].x = getNextPlatformX(highestX);

                    // Обновляем верхние ориентиры для следующей итерации
                    highestY = platforms[i].y; 
                    highestX = platforms[i].x;
                }
            }
        }

        if (player.y > canvas.height) {
            gameState = 'gameover';
            finalScore.innerText = score;
            scoreDisplay.style.display = 'none';
            mobileControls.style.display = 'none';
            gameOverScreen.classList.remove('hidden');
        }
    }

    function loop() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        if (gameState === 'playing') {
            update();
            drawPlatforms();
            drawPlayer();
        }
        animationId = requestAnimationFrame(loop);
    }

    function startGame() {
        mainMenu.classList.add('hidden');
        gameOverScreen.classList.add('hidden');
        scoreDisplay.style.display = 'block';
        mobileControls.style.display = 'block';
        resetGame();
        gameState = 'playing';
    }

    startBtn.addEventListener('click', startGame);
    restartBtn.addEventListener('click', startGame);

    resetGame();
    loop();
</script>

</body>
</html>"

"<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <title>Крестики-Нолики</title>
    <style>
        body {
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            background: #f0f0f0;
            margin: 0;
            padding: 20px;
        }
        .status {
            font-size: 20px;
            margin-bottom: 15px;
            font-weight: bold;
        }
        .board {
            display: grid;
            grid-template-columns: repeat(3, 80px);
            grid-template-rows: repeat(3, 80px);
            gap: 5px;
        }
        .cell {
            width: 80px;
            height: 80px;
            background: #fff;
            border: 2px solid #ccc;
            border-radius: 8px;
            font-size: 36px;
            font-weight: bold;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            user-select: none;
        }
        .cell:hover { background: #e6e6e6; }
        .cell.X { color: #ff4d4d; }
        .cell.O { color: #3b82f6; }
        .btn {
            margin-top: 15px;
            padding: 8px 16px;
            font-size: 16px;
            cursor: pointer;
            border-radius: 4px;
            border: 1px solid #999;
            background: #fff;
        }
        .btn:hover { background: #ddd; }
    </style>
</head>
<body>

    <div class="status" id="status">Твой ход (X)</div>
    <div class="board" id="board"></div>
    <button class="btn" onclick="resetGame()">Заново</button>

<script>
    const boardElement = document.getElementById('board');
    const statusElement = document.getElementById('status');
    let board = ["", "", "", "", "", "", "", "", ""];
    let isGameActive = true;

    const winningConditions = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8], // Строки
        [0, 3, 6], [1, 4, 7], [2, 5, 8], // Столбцы
        [0, 4, 8], [2, 4, 6]             // Диагонали
    ];

    function createBoard() {
        boardElement.innerHTML = "";
        board.forEach((cell, index) => {
            const cellElement = document.createElement('div');
            cellElement.classList.add('cell');
            if (cell) cellElement.classList.add(cell);
            cellElement.innerText = cell;
            cellElement.addEventListener('click', () => handleCellClick(index));
            boardElement.appendChild(cellElement);
        });
    }

    function handleCellClick(index) {
        if (board[index] !== "" || !isGameActive) return;

        board[index] = "X";
        createBoard();
        if (checkWin("X")) {
            statusElement.innerText = "Ты победил! 🎉";
            isGameActive = false;
            return;
        }
        if (board.every(cell => cell !== "")) {
            statusElement.innerText = "Ничья! 🤝";
            isGameActive = false;
            return;
        }

        isGameActive = false; // Блокируем ход игрока на время «думы» ИИ
        statusElement.innerText = "Компьютер думает...";
        setTimeout(aiTurn, 400);
    }

    function aiTurn() {
        let emptyCells = [];
        board.forEach((cell, index) => {
            if (cell === "") emptyCells.push(index);
        });

        if (emptyCells.length > 0) {
            const randomIndex = emptyCells[Math.floor(Math.random() * emptyCells.length)];
            board[randomIndex] = "O";
            createBoard();

            if (checkWin("O")) {
                statusElement.innerText = "Компьютер выиграл! 🤖";
                isGameActive = false;
                return;
            }
            if (board.every(cell => cell !== "")) {
                statusElement.innerText = "Ничья! 🤝";
                isGameActive = false;
                return;
            }
        }
        isGameActive = true;
        statusElement.innerText = "Твой ход (X)";
    }

    function checkWin(player) {
        return winningConditions.some(condition => {
            return condition.every(index => board[index] === player);
        });
    }

    function resetGame() {
        board = ["", "", "", "", "", "", "", "", ""];
        isGameActive = true;
        statusElement.innerText = "Твой ход (X)";
        createBoard();
    }

    createBoard();
</script>
</body>
</html>"

"<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <title>Сапер</title>
    <style>
        body {
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            background: #f0f0f0;
            margin: 0;
            padding: 20px;
        }
        .status {
            font-size: 18px;
            margin-bottom: 10px;
            font-weight: bold;
        }
        .instructions {
            font-size: 12px;
            color: #666;
            margin-bottom: 15px;
        }
        .grid {
            display: grid;
            grid-template-columns: repeat(8, 35px);
            grid-template-rows: repeat(8, 35px);
            gap: 2px;
            background: #999;
            padding: 4px;
            border-radius: 4px;
        }
        .cell {
            width: 35px;
            height: 35px;
            background: #ccc;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            cursor: pointer;
            user-select: none;
            border-top: 3px solid #fff;
            border-left: 3px solid #fff;
            border-bottom: 3px solid #777;
            border-right: 3px solid #777;
            box-sizing: border-box;
        }
        .cell.revealed {
            background: #ddd;
            border: 1px solid #aaa;
        }
        .cell.mine { background: #ff4d4d; }
        .cell.flag { background: #ffeb3b; }
        .btn {
            margin-top: 15px;
            padding: 8px 16px;
            cursor: pointer;
        }
        /* Цвет цифр */
        .c1 { color: blue; }
        .c2 { color: green; }
        .c3 { color: red; }
        .c4 { color: darkblue; }
    </style>
</head>
<body>

    <div class="status" id="mine-status">Сапер (Мин: 10)</div>
    <div class="instructions">Клик — открыть | Ctrl + Клик — поставить флажок 🚩</div>
    <div class="grid" id="grid"></div>
    <button class="btn" onclick="startGame()">Перезапуск</button>

<script>
    const width = 8;
    const bombAmount = 10;
    const grid = document.getElementById('grid');
    const statusTxt = document.getElementById('mine-status');
    let squares = [];
    let isGameOver = false;

    function startGame() {
        grid.innerHTML = "";
        squares = [];
        isGameOver = false;
        statusTxt.innerText = "Сапер (Мин: 10)";

        // Создаем перемешанный массив с бомбами
        const bombsArray = Array(bombAmount).fill('bomb');
        const emptyArray = Array(width * width - bombAmount).fill('valid');
        const gameArray = emptyArray.concat(bombsArray).sort(() => Math.random() - 0.5);

        for(let i = 0; i < width * width; i++) {
            const square = document.createElement('div');
            square.setAttribute('id', i);
            square.classList.add('cell');
            square.dataset.type = gameArray[i];
            grid.appendChild(square);
            squares.push(square);

            // Обработка клика
            square.addEventListener('click', function(e) {
                if (e.ctrlKey) {
                    addFlag(square);
                } else {
                    clickSquare(square);
                }
            });

            // Защита от контекстного меню (чтобы ПКМ не мешал в OS)
            square.addEventListener('contextmenu', e => {
                e.preventDefault();
                addFlag(square);
            });
        }

        // Считаем мины вокруг каждой клетки
        for (let i = 0; i < squares.length; i++) {
            let total = 0;
            const isLeftEdge = (i % width === 0);
            const isRightEdge = (i % width === width - 1);

            if (squares[i].dataset.type === 'valid') {
                if (i > 0 && !isLeftEdge && squares[i - 1].dataset.type === 'bomb') total++;
                if (i > 7 && !isRightEdge && squares[i + 1 - width].dataset.type === 'bomb') total++;
                if (i > 8 && squares[i - width].dataset.type === 'bomb') total++;
                if (i > 9 && !isLeftEdge && squares[i - 1 - width].dataset.type === 'bomb') total++;
                if (i < 63 && !isRightEdge && squares[i + 1].dataset.type === 'bomb') total++;
                if (i < 56 && !isLeftEdge && squares[i - 1 + width].dataset.type === 'bomb') total++;
                if (i < 54 && !isRightEdge && squares[i + 1 + width].dataset.type === 'bomb') total++;
                if (i < 56 && squares[i + width].dataset.type === 'bomb') total++;
                squares[i].setAttribute('data-total', total);
            }
        }
    }

    function addFlag(square) {
        if (isGameOver || square.classList.contains('revealed')) return;
        if (!square.classList.contains('flag')) {
            square.classList.add('flag');
            square.innerText = '🚩';
        } else {
            square.classList.remove('flag');
            square.innerText = '';
        }
    }

    function clickSquare(square) {
        if (isGameOver || square.classList.contains('revealed') || square.classList.contains('flag')) return;

        if (square.dataset.type === 'bomb') {
            gameOver();
        } else {
            let total = square.getAttribute('data-total');
            square.classList.add('revealed');
            square.style.border = "1px solid #aaa"; 
            if (total != 0) {
                square.innerText = total;
                if(total == 1) square.classList.add('c1');
                if(total == 2) square.classList.add('c2');
                if(total == 3) square.classList.add('c3');
                if(total >= 4) square.classList.add('c4');
                checkWin();
                return;
            }
            checkNeighbours(square.id);
        }
        checkWin();
    }

    // Рекурсивное открытие пустых клеток вокруг
    function checkNeighbours(id) {
        const currentId = parseInt(id);
        const isLeftEdge = (currentId % width === 0);
        const isRightEdge = (currentId % width === width - 1);

        setTimeout(() => {
            if (currentId > 0 && !isLeftEdge) clickSquare(squares[currentId - 1]);
            if (currentId > 7 && !isRightEdge) clickSquare(squares[currentId + 1 - width]);
            if (currentId > 8) clickSquare(squares[currentId - width]);
            if (currentId > 9 && !isLeftEdge) clickSquare(squares[currentId - 1 - width]);
            if (currentId < 63 && !isRightEdge) clickSquare(squares[currentId + 1]);
            if (currentId < 56 && !isLeftEdge) clickSquare(squares[currentId - 1 + width]);
            if (currentId < 54 && !isRightEdge) clickSquare(squares[currentId + 1 + width]);
            if (currentId < 56) clickSquare(squares[currentId + width]);
        }, 10);
    }

    function gameOver() {
        statusTxt.innerText = "Бум! Игра окончена 💥";
        isGameOver = true;
        squares.forEach(square => {
            if (square.dataset.type === 'bomb') {
                square.classList.add('revealed', 'mine');
                square.innerText = '💣';
            }
        });
    }

    function checkWin() {
        let matches = 0;
        for (let i = 0; i < squares.length; i++) {
            if (squares[i].classList.contains('revealed') && squares[i].dataset.type === 'valid') {
                matches++;
            }
        }
        if (matches === (width * width - bombAmount)) {
            statusTxt.innerText = "Вы выиграли! 😎";
            isGameOver = true;
        }
    }

    startGame();
</script>
</body>
</html>"

"<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <title>Space Shooter</title>
    <style>
        body {
            background: #222;
            color: #000;
            font-family: monospace;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            margin: 0;
            padding: 20px;
            user-select: none;
        }
        /* Корпус телефона */
        .phone {
            width: 280px;
            background: #cbd3c5;
            border: 6px solid #4a5343;
            border-radius: 20px;
            padding: 15px;
            box-shadow: 0 10px 0 #2d3329;
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        /* Монохромный экран Nokia */
        .screen-border {
            background: #2b3027;
            padding: 8px;
            border-radius: 5px;
            margin-bottom: 15px;
        }
        canvas {
            background: #849c74; /* Тот самый зеленый цвет */
            display: block;
            image-rendering: pixelated;
            border: 2px solid #1c2019;
        }
        /* Клавиатура телефона */
        .keyboard {
            display: grid;
            grid-template-columns: repeat(3, 60px);
            gap: 10px;
            justify-content: center;
        }
        .key {
            width: 60px;
            height: 40px;
            background: #4a5343;
            color: #fff;
            border-radius: 8px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            font-weight: bold;
            cursor: pointer;
            border-bottom: 3px solid #2d3329;
        }
        .key:active {
            transform: translateY(2px);
            border-bottom-width: 1px;
        }
        .key span {
            font-size: 8px;
            color: #bbb;
        }
        .info {
            color: #fff;
            margin-top: 15px;
            font-size: 12px;
            text-align: center;
            max-width: 280px;
        }
    </style>
</head>
<body>

<div class="phone">
    <div class="screen-border">
        <canvas id="gameCanvas" width="240" height="120"></canvas>
    </div>

    <div class="keyboard">
        <div class="key" id="key-blank1"><span></span></div>
        <div class="key" id="btn-up">2<span>▲</span></div>
        <div class="key" id="key-blank2"><span></span></div>

        <div class="key" id="btn-left">4<span>◀</span></div>
        <div class="key" id="btn-fire">5<span>FIRE</span></div>
        <div class="key" id="btn-right">6<span>▶</span></div>

        <div class="key" id="key-blank3"><span></span></div>
        <div class="key" id="btn-down">8<span>▼</span></div>
        <div class="key" id="key-reset">C<span>RESET</span></div>
    </div>
</div>

<div class="info">
    Управление: Кнопки на экране или Стрелочки + Пробел на клавиатуре ПК.
</div>

<script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = '#1c2019'; 

    let player = { x: 10, y: 54, w: 12, h: 8, speed: 2 };
    let bullets = [];
    let enemies = [];
    let score = 0;
    let lives = 3;
    let isGameOver = false;
    let gameTick = 0;

    let keys = { up: false, down: false, left: false, right: false, fire: false };

    // Клавиатура ПК
    window.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowUp') keys.up = true;
        if (e.key === 'ArrowDown') keys.down = true;
        if (e.key === 'ArrowLeft') keys.left = true;
        if (e.key === 'ArrowRight') keys.right = true;
        if (e.key === ' ' || e.key === 'Spacebar') {
            if (!keys.fire && !isGameOver) fireBullet();
            keys.fire = true;
        }
    });
    window.addEventListener('keyup', (e) => {
        if (e.key === 'ArrowUp') keys.up = false;
        if (e.key === 'ArrowDown') keys.down = false;
        if (e.key === 'ArrowLeft') keys.left = false;
        if (e.key === 'ArrowRight') keys.right = false;
        if (e.key === ' ' || e.key === 'Spacebar') keys.fire = false;
    });

    // Виртуальные кнопки
    setupMobileBtn('btn-up', 'up');
    setupMobileBtn('btn-down', 'down');
    setupMobileBtn('btn-left', 'left');
    setupMobileBtn('btn-right', 'right');

    document.getElementById('btn-fire').addEventListener('mousedown', () => { if(!isGameOver) fireBullet(); });
    document.getElementById('btn-fire').addEventListener('touchstart', (e) => { e.preventDefault(); if(!isGameOver) fireBullet(); });
    document.getElementById('key-reset').addEventListener('click', resetGame);

    function setupMobileBtn(id, dir) {
        const btn = document.getElementById(id);
        btn.addEventListener('mousedown', () => keys[dir] = true);
        btn.addEventListener('mouseup', () => keys[dir] = false);
        btn.addEventListener('mouseleave', () => keys[dir] = false);

        btn.addEventListener('touchstart', (e) => { e.preventDefault(); keys[dir] = true; });
        btn.addEventListener('touchend', (e) => { e.preventDefault(); keys[dir] = false; });
    }

    function fireBullet() {
        bullets.push({ x: player.x + player.w, y: player.y + player.h / 2 - 1, w: 4, h: 2 });
    }

    function resetGame() {
        player = { x: 10, y: 54, w: 12, h: 8, speed: 2 };
        bullets = [];
        enemies = [];
        score = 0;
        lives = 3;
        isGameOver = false;
    }

    function update() {
        if (isGameOver) return;

        gameTick++;

        if (keys.up && player.y > 14) player.y -= player.speed;
        if (keys.down && player.y < canvas.height - player.h) player.y += player.speed;
        if (keys.left && player.x > 0) player.x -= player.speed;
        if (keys.right && player.x < canvas.width / 2) player.x += player.speed;

        bullets.forEach((b, i) => {
            b.x += 4;
            if (b.x > canvas.width) bullets.splice(i, 1);
        });

        if (gameTick % 40 === 0) {
            let enemyY = 16 + Math.random() * (canvas.height - 26);
            enemies.push({ x: canvas.width, y: enemyY, w: 8, h: 8, speed: 1.5 });
        }

        enemies.forEach((e, ei) => {
            e.x -= e.speed;

            if (e.x < player.x + player.w && e.x + e.w > player.x && e.y < player.y + player.h && e.y + e.h > player.y) {
                enemies.splice(ei, 1);
                lives--;
                if (lives <= 0) isGameOver = true;
            }

            if (e.x < -10) enemies.splice(ei, 1);

            bullets.forEach((b, bi) => {
                if (b.x < e.x + e.w && b.x + b.w > e.x && b.y < e.y + e.h && b.y + b.h > e.y) {
                    enemies.splice(ei, 1);
                    bullets.splice(bi, 1);
                    score += 10;
                }
            });
        });
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#1c2019';

        // Верхний интерфейс с новым названием
        ctx.font = '8px monospace';
        ctx.fillText(`SPACE SHOOTER`, 4, 8);
        ctx.fillText(`SCORE:${score}`, 110, 8);
        ctx.fillText(`HP:${'♥'.repeat(lives)}`, canvas.width - 38, 8);
        ctx.fillRect(0, 11, canvas.width, 1); 

        if (isGameOver) {
            ctx.font = '12px monospace';
            ctx.fillText("GAME OVER", canvas.width / 2 - 30, canvas.height / 2 + 5);
            ctx.font = '8px monospace';
