            color: #fff;
            margin-top: 15px;
            font-size: 12px;
            text-align: center;
            max-width: 280px;
        }
    </style>
</head>
<body>

<div class="phone">
    <div class="screen-border">
        <canvas id="gameCanvas" width="240" height="120"></canvas>
    </div>

    <div class="keyboard">
        <div class="key" id="key-blank1"><span></span></div>
        <div class="key" id="btn-up">2<span>▲</span></div>
        <div class="key" id="key-blank2"><span></span></div>

        <div class="key" id="btn-left">4<span>◀</span></div>
        <div class="key" id="btn-fire">5<span>FIRE</span></div>
        <div class="key" id="btn-right">6<span>▶</span></div>

        <div class="key" id="key-blank3"><span></span></div>
        <div class="key" id="btn-down">8<span>▼</span></div>
        <div class="key" id="key-reset">C<span>RESET</span></div>
    </div>
</div>

<div class="info">
    Управление: Кнопки на экране или Стрелочки + Пробел на клавиатуре ПК.
</div>

<script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = '#1c2019'; 

    let player = { x: 10, y: 54, w: 12, h: 8, speed: 2 };
    let bullets = [];
    let enemies = [];
    let score = 0;
    let lives = 3;
    let isGameOver = false;
    let gameTick = 0;

    let keys = { up: false, down: false, left: false, right: false, fire: false };

    // Клавиатура ПК
    window.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowUp') keys.up = true;
        if (e.key === 'ArrowDown') keys.down = true;
        if (e.key === 'ArrowLeft') keys.left = true;
        if (e.key === 'ArrowRight') keys.right = true;
        if (e.key === ' ' || e.key === 'Spacebar') {
            if (!keys.fire && !isGameOver) fireBullet();
            keys.fire = true;
        }
    });
    window.addEventListener('keyup', (e) => {
        if (e.key === 'ArrowUp') keys.up = false;
        if (e.key === 'ArrowDown') keys.down = false;
        if (e.key === 'ArrowLeft') keys.left = false;
        if (e.key === 'ArrowRight') keys.right = false;
        if (e.key === ' ' || e.key === 'Spacebar') keys.fire = false;
    });

    // Виртуальные кнопки
    setupMobileBtn('btn-up', 'up');
    setupMobileBtn('btn-down', 'down');
    setupMobileBtn('btn-left', 'left');
    setupMobileBtn('btn-right', 'right');

    document.getElementById('btn-fire').addEventListener('mousedown', () => { if(!isGameOver) fireBullet(); });
    document.getElementById('btn-fire').addEventListener('touchstart', (e) => { e.preventDefault(); if(!isGameOver) fireBullet(); });
    document.getElementById('key-reset').addEventListener('click', resetGame);

    function setupMobileBtn(id, dir) {
        const btn = document.getElementById(id);
        btn.addEventListener('mousedown', () => keys[dir] = true);
        btn.addEventListener('mouseup', () => keys[dir] = false);
        btn.addEventListener('mouseleave', () => keys[dir] = false);

        btn.addEventListener('touchstart', (e) => { e.preventDefault(); keys[dir] = true; });
        btn.addEventListener('touchend', (e) => { e.preventDefault(); keys[dir] = false; });
    }

    function fireBullet() {
        bullets.push({ x: player.x + player.w, y: player.y + player.h / 2 - 1, w: 4, h: 2 });
    }

    function resetGame() {
        player = { x: 10, y: 54, w: 12, h: 8, speed: 2 };
        bullets = [];
        enemies = [];
        score = 0;
        lives = 3;
        isGameOver = false;
    }

    function update() {
        if (isGameOver) return;

        gameTick++;

        if (keys.up && player.y > 14) player.y -= player.speed;
        if (keys.down && player.y < canvas.height - player.h) player.y += player.speed;
        if (keys.left && player.x > 0) player.x -= player.speed;
        if (keys.right && player.x < canvas.width / 2) player.x += player.speed;

        bullets.forEach((b, i) => {
            b.x += 4;
            if (b.x > canvas.width) bullets.splice(i, 1);
        });

        if (gameTick % 40 === 0) {
            let enemyY = 16 + Math.random() * (canvas.height - 26);
            enemies.push({ x: canvas.width, y: enemyY, w: 8, h: 8, speed: 1.5 });
        }

        enemies.forEach((e, ei) => {
            e.x -= e.speed;

            if (e.x < player.x + player.w && e.x + e.w > player.x && e.y < player.y + player.h && e.y + e.h > player.y) {
                enemies.splice(ei, 1);
                lives--;
                if (lives <= 0) isGameOver = true;
            }

            if (e.x < -10) enemies.splice(ei, 1);

            bullets.forEach((b, bi) => {
                if (b.x < e.x + e.w && b.x + b.w > e.x && b.y < e.y + e.h && b.y + b.h > e.y) {
                    enemies.splice(ei, 1);
                    bullets.splice(bi, 1);
                    score += 10;
                }
            });
        });
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#1c2019';

        // Верхний интерфейс с новым названием
        ctx.font = '8px monospace';
        ctx.fillText(`SPACE SHOOTER`, 4, 8);
        ctx.fillText(`SCORE:${score}`, 110, 8);
        ctx.fillText(`HP:${'♥'.repeat(lives)}`, canvas.width - 38, 8);
        ctx.fillRect(0, 11, canvas.width, 1); 

        if (isGameOver) {
            ctx.font = '12px monospace';
            ctx.fillText("GAME OVER", canvas.width / 2 - 30, canvas.height / 2 + 5);
            ctx.font = '8px monospace';
            ctx.fillText("Нажми C для сброса", canvas.width / 2 - 42, canvas.height / 2 + 20);
            return;
        }

        // Корабль игрока
        ctx.fillRect(player.x, player.y + 2, player.w, player.h - 4);
        ctx.fillRect(player.x + 4, player.y, 4, player.h);

        // Пули
        bullets.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));

        // Враги
        enemies.forEach(e => {
            ctx.fillRect(e.x + 2, e.y + 2, e.w - 4, e.h - 4);
            ctx.fillRect(e.x, e.y, 2, 2);
            ctx.fillRect(e.x + 6, e.y, 2, 2);
            ctx.fillRect(e.x, e.y + 6, 2, 2);
            ctx.fillRect(e.x + 6, e.y + 6, 2, 2);
        });
    }

    function gameLoop() {
        update();
        draw();
        requestAnimationFrame(gameLoop);
    }

    gameLoop();
</script>
</body>
</html>"

