            border-radius: 25px;
            cursor: pointer;
            box-shadow: 0 4px 15px rgba(0, 204, 153, 0.4);
            transition: transform 0.1s;
        }
        .btn:active {
            transform: scale(0.95);
        }
    </style>
</head>
<body>

<div id="game-container">
    <canvas id="gameCanvas"></canvas>

    <div id="game-over-screen">
        <h1>ИГРА ОКОНЧЕНА</h1>
        <p>Поймано шаров: <span id="final-score">0</span></p>
        <button class="btn" onclick="resetGame()">ИГРАТЬ ЕЩЕ</button>
    </div>
</div>

<script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const gameOverScreen = document.getElementById('game-over-screen');
    const finalScoreTxt = document.getElementById('final-score');

    // Настройка размеров под экран устройства
    function resizeCanvas() {
        const container = document.getElementById('game-container');
        canvas.width = container.clientWidth;
        canvas.height = container.clientHeight;
    }
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    // Параметры игры
    let score = 0;
    let lives = 3;
    let isGameOver = false;
    let spawnTimer = 0;

    // Параметры коробки (корзины)
    let basket = {
        x: canvas.width / 2 - 40,
        y: canvas.height - 70,
        w: 80,
        h: 20,
        borderRadius: 8
    };

    // Массив падающих шариков
    let balls = [];

    // Цвета для красивых неоновых шаров
    const ballColors = ['#ff3366', '#00cc99', '#3399ff', '#ffcc00', '#b800ff'];

    // --- Управление (Тач и Мышь) ---
    function moveBasket(clientX) {
        if (isGameOver) return;
        const rect = canvas.getBoundingClientRect();
        const relativeX = clientX - rect.left;

        // Держим коробку по центру пальца/курсора и не даем вылететь за края
        basket.x = relativeX - basket.w / 2;
        if (basket.x < 0) basket.x = 0;
        if (basket.x > canvas.width - basket.w) basket.x = canvas.width - basket.w;
    }

    // Слушатели для мыши
    canvas.addEventListener('mousemove', (e) => moveBasket(e.clientX));
    // Слушатели для тач-экранов смартфонов
    canvas.addEventListener('touchmove', (e) => {
        moveBasket(e.touches[0].clientX);
    }, { passive: true });

    function spawnBall() {
        const radius = 10 + Math.random() * 8; // Разные размеры
        const x = radius + Math.random() * (canvas.width - radius * 2);
        const speed = 3 + Math.random() * 4 + (score * 0.1); // Скорость растет со счетом
        const color = ballColors[Math.floor(Math.random() * ballColors.length)];

        balls.push({ x, y: -radius, radius, speed, color });
    }

    function resetGame() {
        score = 0;
        lives = 3;
        balls = [];
        isGameOver = false;
        basket.x = canvas.width / 2 - basket.w / 2;
        basket.y = canvas.height - 70; // На случай если размер изменился
        gameOverScreen.style.display = 'none';
    }

    function update() {
        if (isGameOver) return;

        // Спавн шаров по таймеру (частота зависит от текущего счета)
        spawnTimer++;
        const spawnRate = Math.max(20, 60 - Math.floor(score / 5));
        if (spawnTimer >= spawnRate) {
            spawnBall();
            spawnTimer = 0;
        }

        // Движение шаров
        for (let i = balls.length - 1; i >= 0; i--) {
            let b = balls[i];
            b.y += b.speed;

            // Проверка пойман ли шар коробкой (коллизия)
            if (b.y + b.radius >= basket.y && 
                b.y - b.radius <= basket.y + basket.h &&
                b.x + b.radius >= basket.x && 
                b.x - b.radius <= basket.x + basket.w) {

                balls.splice(i, 1);
                score++;
                continue;
            }

            // Улетел за экран (промах)
            if (b.y - b.radius > canvas.height) {
                balls.splice(i, 1);
                lives--;
                if (lives <= 0) {
                    isGameOver = true;
                    finalScoreTxt.innerText = score;
                    gameOverScreen.style.display = 'flex';
                }
            }
        }
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // 1. Отрисовка интерфейса (Счет и жизни)
        ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
        ctx.font = 'bold 18px system-ui';
        ctx.fillText(`Счет: ${score}`, 20, 40);

        ctx.fillStyle = '#ff3366';
        ctx.fillText(`Жизни: ${'♥'.repeat(lives)}`, canvas.width - 110, 40);

        // 2. Отрисовка коробки (с закругленными краями и неоновой тенью)
        ctx.fillStyle = '#00cc99';
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#00cc99';

        ctx.beginPath();
        ctx.roundRect(basket.x, basket.y, basket.w, basket.h, basket.borderRadius);
        ctx.fill();

        // 3. Отрисовка шаров
        balls.forEach(b => {
            ctx.fillStyle = b.color;
            ctx.shadowColor = b.color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
            ctx.fill();
        });

        // Сбрасываем тень, чтобы не размывать текст на следующем кадре
        ctx.shadowBlur = 0;
    }

    function gameLoop() {
        update();
        draw();
        requestAnimationFrame(gameLoop);
    }

    gameLoop();
</script>
</body>
</html>"

