"<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport"
content="width=device-width,
initial-scale=1,
maximum-scale=1,
user-scalable=no">

<title>Tetris Fixed</title>

<style>

html,body{
  margin:0;
  padding:0;
  overflow:hidden;

  background:#111;
  color:white;

  font-family:Arial;

  display:flex;
  flex-direction:column;
  align-items:center;
}

h1{
  margin:10px;
}

#game{

  display:grid;

  grid-template-columns:
    repeat(10,30px);

  grid-template-rows:
    repeat(20,30px);

  gap:1px;

  background:#000;

  border:4px solid #555;

  margin-top:10px;
}

.cell{

  width:30px;
  height:30px;

  background:#111;

  transition:0.05s;
}

.controls{
  margin-top:15px;
}

.controls button{

  font-size:22px;

  padding:10px;

  margin:5px;

  background:#222;
  color:white;

  border:none;
  border-radius:10px;
}

</style>
</head>

<body>

<h1>Tetris</h1>

<div>
Score:
<span id="score">0</span>
</div>

<div id="game"></div>

<div class="controls">

<button onclick="move(-1,0)">
◀
</button>

<button onclick="move(1,0)">
▶
</button>

<button onclick="move(0,1)">
▼
</button>

<button onclick="rotatePiece()">
⟳
</button>

</div>

<script>

/* BOARD */

const COLS = 10;
const ROWS = 20;

const game =
  document.getElementById("game");

/* CREATE CELLS */

const cells = [];

for(let i=0;i<ROWS*COLS;i++){

  const div =
    document.createElement("div");

  div.className="cell";

  game.appendChild(div);

  cells.push(div);
}

/* SHAPES */

const SHAPES = {

I:[
 [1,1,1,1]
],

O:[
 [1,1],
 [1,1]
],

T:[
 [0,1,0],
 [1,1,1]
],

L:[
 [0,0,1],
 [1,1,1]
]

};

const COLORS = {

I:"#00ffff",
O:"#ffff00",
T:"#aa00ff",
L:"#ff8800"

};

/* GAME DATA */

let board =
  Array.from(
    {length:ROWS},
    ()=>Array(COLS).fill(0)
  );

let piece =
  randomPiece();

let score = 0;

/* RANDOM */

function randomPiece(){

  const keys =
    Object.keys(SHAPES);

  const type =
    keys[Math.random()*keys.length|0];

  return {

    type:type,

    shape:SHAPES[type],

    x:3,

    y:0

  };

}

/* DRAW */

function draw(){

  let temp =
    board.map(r=>[...r]);

  piece.shape.forEach((row,y)=>{

    row.forEach((v,x)=>{

      if(v){

        let px =
          piece.x+x;

        let py =
          piece.y+y;

        if(
          py>=0 &&
          py<ROWS &&
          px>=0 &&
          px<COLS
        ){

          temp[py][px] =
            piece.type;

        }

      }

    });

  });

  let i=0;

  temp.forEach(row=>{

    row.forEach(cell=>{

      cells[i].style.background =
        cell
        ? COLORS[cell]
        : "#111";

      i++;

    });

  });

  document.getElementById("score")
  .innerText=score;
}

/* COLLISION */

function collide(p){

  for(let y=0;y<p.shape.length;y++){

    for(let x=0;x<p.shape[y].length;x++){

      if(!p.shape[y][x])
        continue;

      let px =
        p.x+x;

      let py =
        p.y+y;

      if(
        px<0 ||
        px>=COLS ||
        py>=ROWS
      ){
        return true;
      }

      if(
        py>=0 &&
        board[py][px]
      ){
        return true;
      }

    }

  }

  return false;
}

/* MERGE */

function merge(){

  piece.shape.forEach((row,y)=>{

    row.forEach((v,x)=>{

      if(v){

        board[piece.y+y]
             [piece.x+x]
             = piece.type;

      }

    });

  });

}

/* CLEAR */

function clearLines(){

  let lines = 0;

  board =
    board.filter(row=>{

      if(row.every(v=>v)){

        lines++;

        return false;
      }

      return true;

    });

  while(board.length<ROWS){

    board.unshift(
      Array(COLS).fill(0)
    );

  }

  score += lines*100;
}

/* MOVE */

function move(dx,dy){

  let p = {

    ...piece,

    x:piece.x+dx,

    y:piece.y+dy

  };

  if(!collide(p)){

    piece = p;

  }else if(dy===1){

    merge();

    clearLines();

    piece =
      randomPiece();

    if(collide(piece)){

      alert("Game Over");

      board =
        Array.from(
          {length:ROWS},
          ()=>Array(COLS).fill(0)
        );

      score = 0;
    }

  }

  draw();
}

/* ROTATE */

function rotatePiece(){

  let rotated =
    piece.shape[0]
    .map((_,i)=>
      piece.shape
      .map(r=>r[i])
      .reverse()
    );

  let p = {

    ...piece,

    shape:rotated

  };

  if(!collide(p)){

    piece = p;

  }

  draw();
}

/* KEYBOARD */

document.addEventListener(
  "keydown",
  e=>{

    if(e.key==="ArrowLeft")
      move(-1,0);

    if(e.key==="ArrowRight")
      move(1,0);

    if(e.key==="ArrowDown")
      move(0,1);

    if(e.key==="ArrowUp")
      rotatePiece();

  }
);

/* GAME LOOP */

function loop(){

  move(0,1);

}

setInterval(loop,500);

/* START */

draw();

</script>

</body>
</html>"

