<body>

<div class="bg" id="bg"></div>

<!-- МЕНЮ -->
<div class="screen" id="menuScreen">

    <div class="title">
        Крестики-<br>
        Нолики.
    </div>

    <div class="menu-box">

        <button class="btn" id="playBtn">
            ▶ Играть
        </button>

        <div class="choice-title">
            Крестик или нолик выберете?
        </div>

        <div class="choice-box">

            <div class="choice selected" id="chooseX">
                ❌
            </div>

            <div class="choice" id="chooseO">
                ⚪
            </div>

        </div>

        <button class="btn" id="exitBtn">
            ✖ Выход
        </button>

    </div>

</div>

<!-- ИГРА -->
<div class="screen hidden" id="gameScreen">

    <div class="status" id="status">
        Ход: X
    </div>

    <div class="board" id="board"></div>

    <div class="controls">

        <button class="small-btn" id="restartBtn">
            🔄 Заново
        </button>

        <button class="small-btn" id="menuBtn">
            🏠 Меню
        </button>

    </div>

</div>

<script>
/* ФОН */
const bg = document.getElementById("bg");

for(let i=0;i<35;i++){

    const bubble = document.createElement("span");

    const size = Math.random()*40+10;

    bubble.style.width = size+"px";
    bubble.style.height = size+"px";
    bubble.style.left = Math.random()*100+"%";
    bubble.style.animationDuration =
        Math.random()*15+10+"s";

    bg.appendChild(bubble);
}

/* ЭКРАНЫ */
const menuScreen = document.getElementById("menuScreen");
const gameScreen = document.getElementById("gameScreen");

const playBtn = document.getElementById("playBtn");
const exitBtn = document.getElementById("exitBtn");

const chooseX = document.getElementById("chooseX");
const chooseO = document.getElementById("chooseO");

const statusText = document.getElementById("status");
const board = document.getElementById("board");

let player = "X";
let bot = "O";

chooseX.onclick = () => {

    player = "X";
    bot = "O";

    chooseX.classList.add("selected");
    chooseO.classList.remove("selected");
};

chooseO.onclick = () => {

    player = "O";
    bot = "X";

    chooseO.classList.add("selected");
    chooseX.classList.remove("selected");
};

exitBtn.onclick = () => {
    alert("Спасибо за игру 😎");
};

/* ИГРА */
let currentPlayer = "X";
let gameActive = true;

let cells = ["","","","","","","","",""];

const winPatterns = [
    [0,1,2],
    [3,4,5],
    [6,7,8],
    [0,3,6],
    [1,4,7],
    [2,5,8],
    [0,4,8],
    [2,4,6]
];

playBtn.onclick = () => {

    menuScreen.classList.add("hidden");
    gameScreen.classList.remove("hidden");

    restartGame();

    if(bot === "X"){
        setTimeout(botMove,500);
    }
};

function createBoard(){

    board.innerHTML = "";

    cells.forEach((cell,index)=>{

        const cellDiv = document.createElement("div");

        cellDiv.classList.add("cell");

        if(cell === "X") cellDiv.classList.add("x");
        if(cell === "O") cellDiv.classList.add("o");

        cellDiv.textContent = cell;

        cellDiv.addEventListener("click",()=>{
            playerMove(index);
        });

        board.appendChild(cellDiv);
    });
}

function playerMove(index){

    if(!gameActive) return;

    if(currentPlayer !== player) return;

    if(cells[index] !== "") return;

    cells[index] = player;

    createBoard();

    if(checkWinner()) return;

    currentPlayer = bot;

    statusText.textContent = `Ход: ${bot}`;

    setTimeout(botMove,500);
}

function botMove(){

    if(!gameActive) return;

    let emptyIndexes = [];

    for(let i=0;i<cells.length;i++){

        if(cells[i] === ""){
            emptyIndexes.push(i);
        }
    }

    if(emptyIndexes.length === 0) return;

    const randomIndex =
        emptyIndexes[
            Math.floor(Math.random()*emptyIndexes.length)
        ];

    cells[randomIndex] = bot;

    createBoard();

    if(checkWinner()) return;

    currentPlayer = player;

    statusText.textContent = `Ход: ${player}`;
}

function checkWinner(){

    for(const pattern of winPatterns){

        const [a,b,c] = pattern;

        if(
            cells[a] &&
            cells[a] === cells[b] &&
            cells[a] === cells[c]
        ){

            gameActive = false;

            statusText.textContent =
                `Победил ${cells[a]} 🎉`;

            return true;
        }
    }

    if(!cells.includes("")){

        gameActive = false;

        statusText.textContent = "Ничья 🤝";

        return true;
    }

    return false;
}

function restartGame(){

    currentPlayer = "X";
    gameActive = true;

    cells = ["","","","","","","","",""];

    statusText.textContent = "Ход: X";

    createBoard();

    if(bot === "X"){
        setTimeout(botMove,500);
    }
}

document.getElementById("restartBtn").onclick =
restartGame;

document.getElementById("menuBtn").onclick = () => {

    gameScreen.classList.add("hidden");
    menuScreen.classList.remove("hidden");

    restartGame();
};

createBoard();
</script>

</body>
</html>"

"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>IV PRODUCTION</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;900&display=swap');

        :root {
            --gold-light: #fff2c8;
            --gold-base: #d4af37;
            --gold-dark: #8a6a1c;
        }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            background-color: #000000;
            overflow: hidden;
            display: flex;
            justify-content: center;
            align-items: center;
            font-family: 'Cinzel', serif;
            user-select: none;
            touch-action: none;
        }

        .atmosphere-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 1;
        }

        .dust-particle {
            position: absolute;
            background: rgba(255, 235, 170, 0.4);
            border-radius: 50%;
            opacity: 0;
            animation: dustFloat linear forwards;
        }

        @keyframes dustFloat {
            0% { transform: translateY(5vh) scale(0.8); opacity: 0; }
            50% { opacity: 0.6; }
            100% { transform: translateY(-40vh) scale(1); opacity: 0; }
        }

        #scene-container {
            position: relative;
            z-index: 2;
            display: flex;
            flex-direction: column;
            align-items: center;
            transform: translateZ(0);
        }

        #made-container {
            position: absolute;
            top: -4vh;
            display: flex;
            justify-content: center;
            width: 100%;
            color: var(--gold-light);
            font-size: clamp(0.8rem, 2vw, 1.4rem);
            letter-spacing: 0.8em;
            font-weight: 500;
            opacity: 0;
            transform: translateY(5px);
            transition: opacity 2s ease, transform 3s ease;
            z-index: 3;
        }

        .made-half {
            display: inline-block;
            transition: transform 2.5s ease, opacity 2s ease;
        }

        #logo-container {
            display: flex;
            font-size: clamp(2.2rem, 6.5vw, 5.5rem);
            letter-spacing: 0.08em;
            font-weight: 900;
            z-index: 2;
        }

        .letter {
            position: relative;
            display: inline-block;
            color: transparent;
            opacity: 0;
            margin: 0 0.02em; 
            transform: translateZ(0);
        }

        .letter::before {
            content: attr(data-char);
            position: absolute;
            top: 0; left: 0;
            background: linear-gradient(180deg, var(--gold-light) 0%, var(--gold-base) 45%, var(--gold-dark) 75%, var(--gold-light) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-size: 100% 200%;
            background-position: 0% 0%;
            z-index: 3;
            transition: background-position 0.6s ease, transform 0.4s ease;
            transform: translateZ(0);
        }

        .anim-appear {
            animation: letterEmerge 1.8s forwards ease-out;
        }

        @keyframes letterEmerge {
            0% {
                opacity: 0;
                transform: translateY(10px) scale(0.95);
            }
            100% {
                opacity: 1;
                transform: translateY(0) scale(1);
            }
        }

        .shining::before {
            background-position: 0% 100%;
            transform: scale(1.05);
        }

        .dying {
            transition: opacity 1.5s ease, transform 2s ease;
            opacity: 0 !important;
            transform: translateY(8px) scale(0.98);
        }

.flicker {
            animation: slightFlicker 0.2s ease-in-out;
        }
        @keyframes slightFlicker {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.7; }
        }
    </style>
</head>
<body>

    <div class="atmosphere-container">
        <div id="particle-system"></div>
    </div>

    <div id="scene-container">
        <div id="made-container">
            <span id="made-left" class="made-half">MA</span>
            <span id="made-right" class="made-half">DE</span>
        </div>
        <div id="logo-container"></div>
    </div>

    <script>
        window.addEventListener('touchmove', function(e) {
            e.preventDefault();
        }, { passive: false });

        const TIMINGS = {
            startDelay: 1500,
            letterInterval: 180,
            postAssemblyDelay: 1200,
            madeHold: 2000,
            madeSplitDelay: 1200,
            shineInterval: 120,
            mainHold: 3500,
            disappearInterval: 180,
            finalBlackHold: 2000
        };

        const LOGO_TEXT = "IVPRODUCTION";
        const container = document.getElementById('logo-container');
        const madeContainer = document.getElementById('made-container');
        const letters = [];

        const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

        function buildLogo() {
            for (let i = 0; i < LOGO_TEXT.length; i++) {
                const span = document.createElement('span');
                span.textContent = LOGO_TEXT[i];
                span.className = 'letter';
                span.setAttribute('data-char', LOGO_TEXT[i]);
                container.appendChild(span);
                letters.push(span);
            }
        }

        function initParticles() {
            const pSystem = document.getElementById('particle-system');
            if (pSystem.children.length > 12) return;

            const p = document.createElement('div');
            p.className = 'dust-particle';
            const size = Math.random() * 2 + 1;
            p.style.width = size + 'px';
            p.style.height = size + 'px';
            p.style.left = (Math.random() * 40 + 30) + 'vw';
            p.style.top = (Math.random() * 30 + 40) + 'vh';
            p.style.animationDuration = (Math.random() * 3 + 3) + 's';

            pSystem.appendChild(p);
            setTimeout(() => p.remove(), 6000);
        }

        function triggerCallback() {
            try {
                if (window.Android && typeof window.Android.postMessage === 'function') {
                    window.Android.postMessage("X");
                } else if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.Android) {
                    window.webkit.messageHandlers.Android.postMessage("X");
                } else {
                    window.postMessage("X", "*");
                }
            } catch (e) {
                console.error(e);
            }
        }

        async function runCinematicIntro() {
            buildLogo();

            const particleInterval = setInterval(initParticles, 400);
            await sleep(TIMINGS.startDelay);

            for (let i = 0; i < letters.length; i++) {
                letters[i].classList.add('anim-appear');
                await sleep(TIMINGS.letterInterval);
            }

            await sleep(TIMINGS.postAssemblyDelay);

            madeContainer.style.opacity = '1';
            madeContainer.style.transform = 'translateY(0)';

            await sleep(TIMINGS.madeHold);

            const madeLeft = document.getElementById('made-left');
            const madeRight = document.getElementById('made-right');

            madeLeft.style.transform = 'translateX(-60px)';
            madeLeft.style.opacity = '0';
            madeRight.style.transform = 'translateX(60px)';
            madeRight.style.opacity = '0';

            await sleep(TIMINGS.madeSplitDelay);

document.getElementById('scene-container').classList.add('flicker');
            await sleep(200);
            document.getElementById('scene-container').classList.remove('flicker');

            for (let i = letters.length - 1; i >= 0; i--) {
                letters[i].classList.add('shining');
                setTimeout(() => {
                    if(!letters[i].classList.contains('dying')) {
                        letters[i].classList.remove('shining');
                    }
                }, 500); 
                await sleep(TIMINGS.shineInterval);
            }

            await sleep(TIMINGS.mainHold);

            clearInterval(particleInterval);

            for (let i = letters.length - 1; i >= 0; i--) {
                letters[i].classList.remove('anim-appear', 'shining');
                void letters[i].offsetWidth;
                letters[i].classList.add('dying');
                await sleep(TIMINGS.disappearInterval);
            }

            await sleep(TIMINGS.finalBlackHold);
            triggerCallback();
        }

        window.addEventListener('DOMContentLoaded', runCinematicIntro);
    </script>
</body>
</html>"

